#!/usr/bin/env bash
# Scénario RTK-04 — bucket S3 public oublié (AWS CloudShell)
set -euo pipefail
BUCKET="{{org}}-{{env}}-{{suffix}}"
REGION="{{region}}"

aws s3api create-bucket --bucket "$BUCKET" --region "$REGION" \
  --create-bucket-configuration LocationConstraint="$REGION"

echo "decoy-internal-report" > decoy.txt
aws s3 cp decoy.txt "s3://$BUCKET/decoy.txt"

# Mauvaise configuration volontaire : accès public en lecture
aws s3api put-public-access-block --bucket "$BUCKET" \
  --public-access-block-configuration BlockPublicAcls=false,IgnorePublicAcls=false,BlockPublicPolicy=false,RestrictPublicBuckets=false
aws s3api put-bucket-policy --bucket "$BUCKET" --policy '{
  "Version": "2012-10-17",
  "Statement": [{
    "Sid": "PublicReadDecoy",
    "Effect": "Allow",
    "Principal": "*",
    "Action": "s3:GetObject",
    "Resource": "arn:aws:s3:::'"$BUCKET"'/*"
  }]
}'

# Tags pour traçabilité / nettoyage
aws s3api put-bucket-tagging --bucket "$BUCKET" --tagging '{
  "TagSet": [
    {"Key": "redteam", "Value": "authorized"},
    {"Key": "engagement", "Value": "{{engagement_id}}"}
  ]
}'

# Activer les logs d'accès serveur (pour consultation ultérieure)
aws s3api create-bucket --bucket "${BUCKET}-logs-sink" --region "$REGION" \
  --create-bucket-configuration LocationConstraint="$REGION" || true
aws s3api put-bucket-logging --bucket "$BUCKET" --bucket-logging-status '{
  "LoggingEnabled": {"TargetBucket": "'"$BUCKET"'-logs-sink", "TargetPrefix": "access-logs/"}
}'

echo "Bucket public créé : s3://$BUCKET (region $REGION)"

