#!/usr/bin/env bash
# Scénario RTK-07 — policy IAM trop permissive (AWS CloudShell)
set -euo pipefail
ROLE="{{role_name}}"

cat > policy.json << 'EOF'
{
  "Version": "2012-10-17",
  "Statement": [
    { "Effect": "Allow", "Action": ["*"], "Resource": ["*"] }
  ]
}
EOF

aws iam create-policy --policy-name "$ROLE" --policy-document file://policy.json \
  --tags Key=redteam,Value=authorized Key=engagement,Value={{engagement_id}}

mkdir -p policies
cat > policies/lab-role.json << 'EOF'
{
  "Statement": [
    { "Effect": "Allow", "Action": ["*"], "Resource": ["*"] }
  ]
}
EOF

echo "Policy créée : $ROLE — fichier d'analyse RTK : policies/lab-role.json"

